import { chromium } from '/root/workspace/ha-lovelace-extended/experiments/minimum-card-contract/node_modules/playwright/index.mjs';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { homedir } from 'node:os';
import { randomBytes } from 'node:crypto';
import { resolve } from 'node:path';
export const base = 'http://127.0.0.1:18124';
export const area = process.env.MCC_RESEARCH || resolve(homedir(), 'research/ha-lovelace-extended/demonstrate-fixed-composition-card');
export const state = resolve(homedir(), '.local/state/ha-lovelace-extended/fixed-composition-card');
const tokenPath = resolve(state, 'tokens.json');
export async function tokens() {
  let saved;
  try { saved = JSON.parse(await readFile(tokenPath, 'utf8')); } catch (e) { if (e.code !== 'ENOENT') throw e; }
  let data;
  if (!saved) {
    const credentials = { name: 'Experiment', username: 'mcc', password: randomBytes(24).toString('base64url'), client_id: base + '/', language: 'en' };
    const response = await fetch(base + '/api/onboarding/users', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(credentials)});
    if (!response.ok) throw new Error('Disposable user creation failed: ' + response.status);
    const { auth_code } = await response.json();
    data = {grant_type:'authorization_code',code:auth_code,client_id:base + '/'};
    await writeFile(resolve(state, 'credentials.json'), JSON.stringify(credentials), {mode:0o600});
  } else {
    data = {grant_type:'refresh_token', refresh_token:saved.refresh_token,client_id:base + '/'};
  }
  const response = await fetch(base + '/auth/token', {method:'POST', body:new URLSearchParams(data)});
  if (!response.ok) throw new Error('Disposable authentication failed: ' + response.status);
  const value = {...saved, ...await response.json(), hassUrl:base,clientId:base + '/'};
  value.expires = Date.now() + value.expires_in * 1000;
  await writeFile(tokenPath, JSON.stringify(value), {mode:0o600});
  return value;
}
export async function createPage(browser, auth, {touch=false, intercept=true, language='en', colorScheme='light'}={}) {
  const context = await browser.newContext({viewport:{width:1280,height:900},deviceScaleFactor:1,locale:language==='pt-BR'?'pt-BR':'en-US',hasTouch:touch,colorScheme,serviceWorkers:'block',proxy:{server:'http://127.0.0.1:9',bypass:'127.0.0.1'}});
  await context.addInitScript(({auth,language}) => {
    localStorage.setItem('hassTokens', JSON.stringify(auth));
  }, {auth,language});
  const page = await context.newPage();
  if (intercept) {
    await page.addInitScript({content:'' + await readFile('/root/research/ha-lovelace-extended/implement-complete-desk-composition/intercept.js', 'utf8')});
  }
  return {context,page};
}
export async function openHA(options={}) {
  const auth = await tokens();
  const browser = await chromium.launch();
  const {context,page} = await createPage(browser,auth,options);
  await page.goto(base + '/lovelace/0');
  await page.waitForFunction(() => !!document.querySelector('home-assistant')?.hass?.states?.['cover.fcc_primary']);
  const confirm = page.getByRole('dialog', {name:'Confirm new HTTP server configuration'});
  await confirm.waitFor({state:'visible',timeout:1500}).catch(() => {});
  if (await confirm.isVisible()) await page.getByRole('button', {name:'Confirm',exact:true}).click({timeout:3000});
  const language=options.language ?? 'en';
  if(await page.evaluate(()=>document.querySelector('home-assistant').hass.language)!==language){
    await ws(page,{type:'frontend/set_user_data',key:'language',value:{language,number_format:'language',time_format:'language',date_format:'language',time_zone:'local',first_weekday:'language'}});
    await page.waitForFunction(language=>document.querySelector('home-assistant').hass.language===language,language);
  }
  await page.locator('#ha-launch-screen').waitFor({state:'hidden'});
  return {browser,context,page,auth};
}
export async function ws(page, message) {
  return page.evaluate(message => document.querySelector('home-assistant').hass.callWS(message), message);
}
export async function result(name, data) {
  await mkdir(area, {recursive:true});
  await writeFile(resolve(area, name + '.json'), JSON.stringify(data, null, 2) + '\n');
}

/* External synthetic lab safety adapter. No call_service reaches send. */
(() => {
 const fixtures = new Set(['cover.fcc_primary','cover.fcc_alternate','sensor.fcc_height','sensor.fcc_alternate','button.fcc_memory_1','button.fcc_memory_2','button.fcc_memory_3']);
 const events=[], blocked=[];
 function validate(message) {
  if(!message || message.type!=='call_service') return false;
  if(Object.keys(message).some(k=>!['id','type','domain','service','service_data','target','return_response'].includes(k))) return false;
  if(message.return_response != null && message.return_response!==false) return false;
  const target=message.target;
  if(target && Object.keys(target).some(k=>k!=='entity_id')) return false;
  if(target?.entity_id!==undefined && message.service_data?.entity_id!==undefined)return false;
  const rawTarget=target?.entity_id??message.service_data?.entity_id;
  const entity=Array.isArray(rawTarget)&&rawTarget.length===1?rawTarget[0]:rawTarget;
  if(typeof entity!=='string'||!fixtures.has(entity)) return false;
  const rawData=message.service_data??{};
  if(!rawData||typeof rawData!=='object'||Array.isArray(rawData))return false;
  const data={...rawData};delete data.entity_id;
  if(!data||typeof data!=='object'||Array.isArray(data))return false;
  if(message.domain==='cover'&&entity.startsWith('cover.')) {
   if(message.service==='set_cover_position')return Object.keys(data).length===1&&Number.isFinite(data.position)&&data.position>=0&&data.position<=100;
   return ['open_cover','close_cover','stop_cover'].includes(message.service)&&Object.keys(data).length===0;
  }
  return message.domain==='button'&&entity.startsWith('button.')&&message.service==='press'&&Object.keys(data).length===0;
 }
 Object.defineProperty(globalThis,'fccLab',{value:{events,blocked,validate,reset(){events.length=0;blocked.length=0;}}});
 const serviceURL=input=>{const u=new URL(input,location.href);return /^\/api\/services(?:\/|$)/.test(decodeURIComponent(u.pathname));};
 const originalFetch=globalThis.fetch;
 globalThis.fetch=function(input,options){if(serviceURL(typeof input==='string'||input instanceof URL?input:input.url)){blocked.push('fetch');return Promise.reject(new Error('Synthetic lab blocks REST services'));}return originalFetch.call(this,input,options);};
 const originalOpen=XMLHttpRequest.prototype.open;
 XMLHttpRequest.prototype.open=function(method,url,...args){if(serviceURL(url)){blocked.push('xhr');throw new Error('Synthetic lab blocks XHR services');}return originalOpen.call(this,method,url,...args);};
 const originalSend=WebSocket.prototype.send;
 WebSocket.prototype.send=function(data){
  let msg;
  try{msg=JSON.parse(data);}catch{blocked.push('malformed-websocket');throw new Error('Non-JSON websocket data denied');}
  if(msg.type!=='call_service')return originalSend.call(this,data);
  const valid=validate(msg);
  blocked.push('websocket-service');
  if(valid)events.push({...structuredClone(msg),recordedAt:performance.now()});
  const response=valid?{id:msg.id,type:'result',success:true,result:{context:{id:'synthetic-only',parent_id:null,user_id:null}}}:{id:msg.id,type:'result',success:false,error:{code:'synthetic_rejected',message:'Descriptor not allowed'}};
  queueMicrotask(()=>this.dispatchEvent(new MessageEvent('message',{data:JSON.stringify(response)})));
 };
})();

