       await store({variant,count,trial,cache,...await capture(page),metrics:await metrics(cdp),valid:true});
      }
     }else for(const row of await editorPair(page,cdp,variant,count,trial))await store(row);
    }finally{await context.close();}
    console.log(phase,variant,count,trial,'complete');
   }
  }
 }else if(phase==='updates'||phase==='inputs'){
  for(const {variant,count}of schedule){
   await resetFixture();await prepare(control,variant,count);
   const {context,page,cdp}=await measuredPage(browser,auth,variant,count);
   try{
    if(phase==='updates')for(const rate of [1,20])for(const related of [true,false])await store(await updateWindow(page,cdp,{variant,count,rate,related}));
    else {await store({variant,count,phase:'idle',...await inputTrials(page,variant,pilot?2:10),valid:true});await store({...await updateWindow(page,cdp,{variant,count,rate:20,related:true,input:true}),phase:'under-updates'});}
   }finally{await context.close();}
   console.log(phase,variant,count,'complete');
  }
 }else throw new Error('Unknown profile phase');
}catch(error){await store({valid:false,error:error.message});throw error;}finally{await resetFixture().catch(()=>{});await browser.close();}
console.log(JSON.stringify({phase,observations:samples.length,valid:samples.filter(r=>r.valid).length}));
